{
  "summary": "Créer un instrument pour calculer la valeur minimax du jeu d'allocation de ressources à somme nulle décrit dans l'ambition.",
  "actions": [
    {
      "tool": "construct_instrument",
      "name": "minimax.json",
      "spec": {
        "name": "MinimaxCalculator",
        "inputs": ["allocation", "scenarios", "weights"],
        "outputs": {
          "minimax_value": {
            "args": [
              {"field": "allocation"},
              {"field": "scenarios"},
              {"field": "weights"}
            ],
            "op": "minimax"
          }
        }
      }
    },
    {
      "tool": "write_dataset",
      "name": "data.csv",
      "columns": ["allocation", "scenarios", "weights"],
      "rows": [
        [1, [{"scenario": "alpha", "weights": [9, 2]}, {"scenario": "beta", "weights": [4, 13]}], [9, 2, 4, 13]]
      ]
    },
    {
      "tool": "run_instrument",
      "name": "minimax.json",
      "input": {
        "allocation": 1,
        "scenarios": [{"scenario": "alpha", "weights": [9, 2]}, {"scenario": "beta", "weights": [4, 13]}],
        "weights": [9, 2, 4, 13]
      }
    }
  ],
  "done": false
}
